{
  "findings": [
    {
      "check_id": "CKV_AWS_364",
      "title": "Lambda invocation permission is not restricted by source account",
      "resource": "aws_lambda_permission.api_gateway_invoke",
      "severity": "MEDIUM",
      "explanation": "The API Gateway service principal can invoke the Lambda function without a SourceArn or SourceAccount restriction, creating a confused-deputy risk from API Gateway resources in other AWS accounts."
    }
  ],
  "patched_code": "resource \"aws_lambda_permission\" \"api_gateway_invoke\" {\n  statement_id  = \"AllowExecutionFromAPIGateway\"\n  action        = \"lambda:InvokeFunction\"\n  function_name = aws_lambda_function.log_processing_pipeline.function_name\n  principal     = \"apigateway.amazonaws.com\"\n  source_account = split(\":\", aws_lambda_function.log_processing_pipeline.arn)[4]\n}\n",
  "fix_summary": "Restricted the API Gateway invocation permission to the AWS account that owns the referenced Lambda function by setting source_account."
}
